final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: IoT Core policy for device onboarding with Lambda-backed custom resource

Parameters:
  TopicPrefix:
    Type: String
    Default: devices
    Description: Topic prefix for device-specific publish and subscribe topics

Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IoTPolicyManagement
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:CreatePolicyVersion
                  - iot:SetDefaultPolicyVersion
                  - iot:ListPolicyVersions
                  - iot:DeletePolicyVersion
                Resource: !Sub 'arn:aws:iot:${AWS::Region}:${AWS::AccountId}:policy/*'

  LambdaFunction:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: !Sub '${AWS::StackName}-IoTPolicyLambda'
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Runtime: nodejs24.x
      Timeout: 30
      Code:
        ZipFile: |
          const https = require('https');
          const {
            IoTClient,
            CreatePolicyCommand,
            DeletePolicyCommand,
            CreatePolicyVersionCommand,
            ListPolicyVersionsCommand,
            DeletePolicyVersionCommand
          } = require('@aws-sdk/client-iot');

          const iot = new IoTClient({});

          exports.handler = async (event, context) => {
            console.log('Received event:', JSON.stringify(event, null, 2));
            let responseData = {};
            let physicalResourceId = event.PhysicalResourceId;

            try {
              if (event.RequestType === 'Create') {
                const policyName = generatePolicyName(event.StackName);
                const policyDocument = createPolicyDocument(event.TopicPrefix, context);
                await iot.send(new CreatePolicyCommand({
                  policyName: policyName,
                  policyDocument: JSON.stringify(policyDocument)
                }));
                physicalResourceId = policyName;
                responseData.PolicyName = policyName;
              } else if (event.RequestType === 'Update') {
                const policyName = event.PhysicalResourceId;
                const policyDocument = createPolicyDocument(event.TopicPrefix, context);
                await iot.send(new CreatePolicyVersionCommand({
                  policyName: policyName,
                  policyDocument: JSON.stringify(policyDocument),
                  setAsDefault: true
                }));
                const versions = await iot.send(new ListPolicyVersionsCommand({ policyName: policyName }));
                for (const version of versions.policyVersions) {
                  if (!version.isDefaultVersion) {
                    await iot.send(new DeletePolicyVersionCommand({
                      policyName: policyName,
                      policyVersionId: version.versionId
                    }));
                  }
                }
                responseData.PolicyName = policyName;
              } else if (event.RequestType === 'Delete') {
                const policyName = event.PhysicalResourceId;
                try {
                  await iot.send(new DeletePolicyCommand({ policyName: policyName }));
                } catch (err) {
                  if (err.name !== 'ResourceNotFoundException') {
                    throw err;
                  }
                }
                responseData.PolicyName = policyName;
              }

              await sendResponse(event, context, 'SUCCESS', responseData, physicalResourceId);
            } catch (err) {
              console.error('Error:', err);
              await sendResponse(event, context, 'FAILED', {}, physicalResourceId, err.message);
            }
          };

          function generatePolicyName(stackName) {
            const base = 'IoTDevicePolicy';
            const sanitizedStackName = (stackName || 'Stack').replace(/[^a-zA-Z0-9_+=,.@-]/g, '');
            const random = Math.random().toString(36).substring(2, 10);
            let name = `${base}-${sanitizedStackName}-${random}`;
            if (name.length > 128) {
              name = name.substring(0, 128);
            }
            return name;
          }

          function createPolicyDocument(topicPrefix, context) {
            const region = process.env.AWS_REGION;
            const accountId = context.invokedFunctionArn.split(':')[4];
            const thingNameVar = '${iot:Connection.Thing.ThingName}';
            const topicPrefixVal = topicPrefix || 'devices';
            const baseArn = `arn:aws:iot:${region}:${accountId}`;
            return {
              Version: '2012-10-17',
              Statement: [
                {
                  Effect: 'Allow',
                  Action: ['iot:Connect'],
                  Resource: `${baseArn}:client/${thingNameVar}`
                },
                {
                  Effect: 'Allow',
                  Action: ['iot:Publish'],
                  Resource: `${baseArn}:topic/${topicPrefixVal}/${thingNameVar}/*`
                },
                {
                  Effect: 'Allow',
                  Action: ['iot:Subscribe'],
                  Resource: `${baseArn}:topicfilter/${topicPrefixVal}/${thingNameVar}/*`
                },
                {
                  Effect: 'Allow',
                  Action: ['iot:Receive'],
                  Resource: `${baseArn}:topic/${topicPrefixVal}/${thingNameVar}/*`
                }
              ]
            };
          }

          function sendResponse(event, context, status, data, physicalResourceId, reason) {
            const responseBody = JSON.stringify({
              Status: status,
              Reason: reason || `See CloudWatch Log Stream: ${context.logStreamName}`,
              PhysicalResourceId: physicalResourceId || context.logStreamName,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              Data: data
            });

            const parsedUrl = new URL(event.ResponseURL);
            const options = {
              hostname: parsedUrl.hostname,
              port: 443,
              path: parsedUrl.pathname + parsedUrl.search,
              method: 'PUT',
              headers: {
                'content-type': '',
                'content-length': Buffer.byteLength(responseBody)
              }
            };

            return new Promise((resolve, reject) => {
              const request = https.request(options, (response) => {
                console.log('Status code:', response.statusCode);
                response.on('data', (d) => process.stdout.write(d));
                response.on('end', () => {
                  console.log('Response sent');
                  resolve();
                });
              });
              request.on('error', (err) => {
                console.error('Error sending response:', err);
                reject(err);
              });
              request.write(responseBody);
              request.end();
            });
          }

  IoTPolicyCustomResource:
    Type: Custom::IoTPolicy
    Properties:
      ServiceToken: !GetAtt LambdaFunction.Arn
      TopicPrefix: !Ref TopicPrefix
      StackName: !Ref AWS::StackName

Outputs:
  PolicyName:
    Description: Name of the generated IoT policy
    Value: !GetAtt IoTPolicyCustomResource.PolicyName

AWSTemplateFormatVersion: "2010-09-09"
Description: >-
  Amazon Verified Permissions policy store that implements Cedar-based access control for a
  Bookstore application. The stack creates a policy store with a strictly validated Bookstore
  namespace (Role, User, and Book entities; View and ViewWithPremiumOffers actions), attaches a
  set of static Cedar policies, and publishes the policy store ID to AWS Systems Manager
  Parameter Store so other components of the stack can reference it.

Parameters:
  PolicyStoreIdParameterName:
    Type: String
    Default: /bookstore/verified-permissions/policy-store-id
    Description: Name of the SSM Parameter used to publish the Verified Permissions policy store ID.
    MinLength: 1
    MaxLength: 1011
    AllowedPattern: '^[a-zA-Z0-9_.\-/]*$'

Resources:

  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {},
                "User": {
                  "memberOfTypes": ["Role"],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long"
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User"
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  AdminViewAnyBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: |
            permit (
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  ForbidNamedAdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: |
            forbid (
              principal == Bookstore::User::"alice",
              action == Bookstore::Action::"View",
              resource
            );

  PublisherViewOwnedBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: |
            permit (
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when {
              resource.owner == principal
            };

  NamedUserViewNamedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: |
            permit (
              principal == Bookstore::User::"bob",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"TheGreatGatsby"
            );

  CustomerViewPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: |
            permit (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal.yearsAsMember >= 2
            };

  ForbidNewCustomerViewPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: |
            forbid (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal.yearsAsMember < 2
            };

  ForbidViewOutsideUnitedStatesPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: |
            forbid (
              principal,
              action in [
                Bookstore::Action::"View",
                Bookstore::Action::"ViewWithPremiumOffers"
              ],
              resource
            )
            when {
              context.region != "US"
            };

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: !Ref PolicyStoreIdParameterName
      Description: ID of the Amazon Verified Permissions policy store used by the Bookstore application.
      Type: String
      Value: !GetAtt BookstorePolicyStore.PolicyStoreId

Outputs:

  PolicyStoreId:
    Description: ID of the Amazon Verified Permissions policy store.
    Value: !GetAtt BookstorePolicyStore.PolicyStoreId

  PolicyStoreArn:
    Description: ARN of the Amazon Verified Permissions policy store.
    Value: !GetAtt BookstorePolicyStore.Arn

  PolicyStoreIdParameterName:
    Description: Name of the SSM Parameter that holds the Verified Permissions policy store ID.
    Value: !Ref PolicyStoreIdParameter

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Calculator demo stack. Deploys a Node.js 20.x Lambda function named "Calculator"
  that performs add/subtract/multiply/divide on two operands, plus a Step Functions
  state machine named "Calculator-StateMachine" that routes on the requested operator,
  invokes the Lambda for supported operators, and fails for unknown operators.

Resources:

  CalculatorLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/lambda/Calculator
      RetentionInDays: 3

  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: Calculator-LambdaExecutionRole
      Description: Execution role that allows the Calculator Lambda function to write logs to CloudWatch Logs.
      Path: /
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - !Sub arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole

  StepFunctionsExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: Calculator-StateMachineExecutionRole
      Description: Execution role that allows the Calculator state machine to invoke the Calculator Lambda function.
      Path: /
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: InvokeCalculatorLambda
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - lambda:InvokeFunction
                Resource:
                  - !GetAtt Calculator.Arn

  Calculator:
    Type: AWS::Lambda::Function
    DependsOn:
      - CalculatorLogGroup
    Properties:
      FunctionName: Calculator
      Description: Performs add, subtract, multiply or divide on two operands supplied in the event.
      Runtime: nodejs20.x
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      MemorySize: 128
      Timeout: 10
      Code:
        ZipFile: |
          exports.handler = async (event) => {
            const operator = event && event.operator;
            const operands = event && Array.isArray(event.operands) ? event.operands : [];

            if (operands.length !== 2) {
              throw new Error('Expected exactly two operands, for example {"operator":"add","operands":[1,2]}');
            }

            const left = Number(operands[0]);
            const right = Number(operands[1]);

            if (Number.isNaN(left) || Number.isNaN(right)) {
              throw new Error('Both operands must be numbers.');
            }

            let result;

            switch (operator) {
              case 'add':
                result = left + right;
                break;
              case 'subtract':
                result = left - right;
                break;
              case 'multiply':
                result = left * right;
                break;
              case 'divide':
                if (right === 0) {
                  throw new Error('Division by zero is not allowed.');
                }
                result = left / right;
                break;
              default:
                throw new Error('Unsupported operator: ' + operator);
            }

            return {
              operator: operator,
              operands: [left, right],
              result: result
            };
          };

  CalculatorStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      StateMachineType: STANDARD
      RoleArn: !GetAtt StepFunctionsExecutionRole.Arn
      DefinitionString: !Sub
        - |
          {
            "Comment": "Calculator state machine: routes on $.operator and invokes the Calculator Lambda.",
            "StartAt": "ChoiceState",
            "States": {
              "ChoiceState": {
                "Type": "Choice",
                "Comment": "Route to the matching arithmetic operation.",
                "Choices": [
                  {
                    "Variable": "$.operator",
                    "StringEquals": "add",
                    "Next": "AddOperation"
                  },
                  {
                    "Variable": "$.operator",
                    "StringEquals": "subtract",
                    "Next": "SubtractOperation"
                  },
                  {
                    "Variable": "$.operator",
                    "StringEquals": "multiply",
                    "Next": "MultiplyOperation"
                  },
                  {
                    "Variable": "$.operator",
                    "StringEquals": "divide",
                    "Next": "DivideOperation"
                  }
                ],
                "Default": "UnsupportedOperator"
              },
              "AddOperation": {
                "Type": "Task",
                "Comment": "Invoke the Calculator Lambda for an addition.",
                "Resource": "arn:${AWS::Partition}:states:::lambda:invoke",
                "Parameters": {
                  "FunctionName": "${CalculatorArn}",
                  "Payload.$": "$"
                },
                "ResultSelector": {
                  "operator.$": "$.Payload.operator",
                  "operands.$": "$.Payload.operands",
                  "result.$": "$.Payload.result"
                },
                "End": true
              },
              "SubtractOperation": {
                "Type": "Task",
                "Comment": "Invoke the Calculator Lambda for a subtraction.",
                "Resource": "arn:${AWS::Partition}:states:::lambda:invoke",
                "Parameters": {
                  "FunctionName": "${CalculatorArn}",
                  "Payload.$": "$"
                },
                "ResultSelector": {
                  "operator.$": "$.Payload.operator",
                  "operands.$": "$.Payload.operands",
                  "result.$": "$.Payload.result"
                },
                "End": true
              },
              "MultiplyOperation": {
                "Type": "Task",
                "Comment": "Invoke the Calculator Lambda for a multiplication.",
                "Resource": "arn:${AWS::Partition}:states:::lambda:invoke",
                "Parameters": {
                  "FunctionName": "${CalculatorArn}",
                  "Payload.$": "$"
                },
                "ResultSelector": {
                  "operator.$": "$.Payload.operator",
                  "operands.$": "$.Payload.operands",
                  "result.$": "$.Payload.result"
                },
                "End": true
              },
              "DivideOperation": {
                "Type": "Task",
                "Comment": "Invoke the Calculator Lambda for a division.",
                "Resource": "arn:${AWS::Partition}:states:::lambda:invoke",
                "Parameters": {
                  "FunctionName": "${CalculatorArn}",
                  "Payload.$": "$"
                },
                "ResultSelector": {
                  "operator.$": "$.Payload.operator",
                  "operands.$": "$.Payload.operands",
                  "result.$": "$.Payload.result"
                },
                "End": true
              },
              "UnsupportedOperator": {
                "Type": "Fail",
                "Error": "UnsupportedOperator",
                "Cause": "The supplied operator is not supported. Use one of: add, subtract, multiply, divide."
              }
            }
          }
        - CalculatorArn: !GetAtt Calculator.Arn

Outputs:

  SampleInput:
    Description: Sample input payload for starting the Calculator-StateMachine execution.
    Value: '{"operator": "add", "operands": [1,2]}'

  StateMachineName:
    Description: Name of the Calculator Step Functions state machine.
    Value: !GetAtt CalculatorStateMachine.Name

  StateMachineArn:
    Description: ARN of the Calculator Step Functions state machine.
    Value: !Ref CalculatorStateMachine

  CalculatorFunctionName:
    Description: Name of the Calculator Lambda function.
    Value: !Ref Calculator

  CalculatorFunctionArn:
    Description: ARN of the Calculator Lambda function.
    Value: !GetAtt Calculator.Arn

