final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  TodoAPIwithJs - Self-contained AWS AppSync GraphQL API with API key
  authentication, backed by an Amazon DynamoDB table that has an owner global
  secondary index, and implemented with JavaScript (APPSYNC_JS) pipeline
  resolvers for full CRUD operations, owner-index queries and real-time
  subscriptions.

Parameters:
  ApiName:
    Type: String
    Default: TodoAPIwithJs
    MinLength: 1
    MaxLength: 50
    Description: Name of the AppSync GraphQL API.

Resources:

  ############################################################################
  # DynamoDB table (with owner GSI)
  ############################################################################
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      TableName: !Sub '${AWS::StackName}-todo-table'
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      Tags:
        - Key: Name
          Value: !Ref ApiName

  ############################################################################
  # IAM role that AppSync assumes to read/write the DynamoDB table
  ############################################################################
  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: !Sub '${AWS::StackName}-appsync-dynamodb-role'
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoDynamoDBAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  ############################################################################
  # AppSync GraphQL API + API key
  ############################################################################
  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: !Ref ApiName
      AuthenticationType: API_KEY
      Tags:
        - Key: Name
          Value: !Ref ApiName

  ApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Description: API key for the TodoAPIwithJs GraphQL API
      Expires: 1893456000

  ############################################################################
  # GraphQL schema
  ############################################################################
  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          name: String!
          description: String
          owner: String
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          id: ID
          name: String!
          description: String
          owner: String
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        input UpdateTodoInput {
          id: ID!
          name: String
          description: String
          owner: String
          updatedAt: AWSDateTime
        }

        input DeleteTodoInput {
          id: ID!
        }

        input TableTodoFilterInput {
          id: TableIDFilterInput
          name: TableStringFilterInput
          description: TableStringFilterInput
          owner: TableStringFilterInput
          createdAt: TableStringFilterInput
          updatedAt: TableStringFilterInput
          and: [TableTodoFilterInput]
          or: [TableTodoFilterInput]
          not: TableTodoFilterInput
        }

        input TableIDFilterInput {
          ne: ID
          eq: ID
          le: ID
          lt: ID
          ge: ID
          gt: ID
          contains: ID
          notContains: ID
          between: [ID]
          beginsWith: ID
          attributeExists: Boolean
          attributeType: ModelAttributeTypes
          size: ModelSizeInput
        }

        input TableStringFilterInput {
          ne: String
          eq: String
          le: String
          lt: String
          ge: String
          gt: String
          contains: String
          notContains: String
          between: [String]
          beginsWith: String
          attributeExists: Boolean
          attributeType: ModelAttributeTypes
          size: ModelSizeInput
        }

        input ModelSizeInput {
          ne: Int
          eq: Int
          le: Int
          lt: Int
          ge: Int
          gt: Int
          between: [Int]
        }

        enum ModelAttributeTypes {
          binary
          binarySet
          bool
          list
          map
          number
          numberSet
          string
          stringSet
          _null
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(filter: TableTodoFilterInput, limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }

        type Subscription {
          onCreateTodo(owner: String): Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo(owner: String): Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo(owner: String): Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

  ############################################################################
  # Data sources
  ############################################################################
  TodoTableDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region
        UseCallerCredentials: false

  NoneDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: NoneDataSource
      Description: NONE data source used by subscription resolvers
      Type: NONE

  ############################################################################
  # JavaScript functions (APPSYNC_JS runtime)
  ############################################################################
  FnCreateTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: createTodoFunction
      Description: Creates a Todo item in DynamoDB
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input || {};
          const identity = ctx.identity || {};
          const id = input.id || util.autoId();
          const now = util.time.nowISO8601();
          const owner = input.owner || identity.sub || identity.username || 'api-key-user';

          const item = {
            id: id,
            name: input.name,
            description: input.description,
            owner: owner,
            createdAt: input.createdAt || now,
            updatedAt: now,
          };

          Object.keys(item).forEach(function (field) {
            if (item[field] === undefined || item[field] === null) {
              delete item[field];
            }
          });

          const condition = util.transform.toDynamoDBConditionExpression({
            id: { attributeExists: false },
          });

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(item),
            condition: condition,
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  FnUpdateTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: updateTodoFunction
      Description: Updates an existing Todo item in DynamoDB
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input || {};
          const id = input.id;

          const sets = [];
          const expressionNames = {};
          const expressionValues = {};

          Object.keys(input).forEach(function (field) {
            if (field === 'id' || field === 'updatedAt') {
              return;
            }
            const value = input[field];
            if (value === undefined || value === null) {
              return;
            }
            sets.push('#' + field + ' = :' + field);
            expressionNames['#' + field] = field;
            expressionValues[':' + field] = value;
          });

          sets.push('#updatedAt = :updatedAt');
          expressionNames['#updatedAt'] = 'updatedAt';
          expressionValues[':updatedAt'] = util.time.nowISO8601();

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  FnDeleteTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: deleteTodoFunction
      Description: Deletes a Todo item from DynamoDB
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.input.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  FnGetTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: getTodoFunction
      Description: Gets a single Todo item by id
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  FnListTodos:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: listTodosFunction
      Description: Lists Todo items from DynamoDB
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const args = ctx.args || {};
          const request = {
            operation: 'Scan',
            limit: args.limit || 100,
          };

          if (args.nextToken) {
            request.nextToken = args.nextToken;
          }

          if (args.filter) {
            request.filter = util.transform.toDynamoDBFilterExpression(args.filter);
          }

          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items || [],
            nextToken: ctx.result.nextToken,
          };
        }

  FnTodosByOwner:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: todosByOwnerFunction
      Description: Queries Todo items by owner using the owner-index GSI
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const args = ctx.args || {};
          const request = {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': args.owner }),
            },
            limit: args.limit || 100,
          };

          if (args.nextToken) {
            request.nextToken = args.nextToken;
          }

          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items || [],
            nextToken: ctx.result.nextToken,
          };
        }

  FnOnCreateTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: onCreateTodoFunction
      Description: Subscription function for createTodo events
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return null;
        }

  FnOnUpdateTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: onUpdateTodoFunction
      Description: Subscription function for updateTodo events
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return null;
        }

  FnOnDeleteTodo:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: onDeleteTodoFunction
      Description: Subscription function for deleteTodo events
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return null;
        }

  ############################################################################
  # Pipeline resolvers - Query
  ############################################################################
  ResolverGetTodo:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnGetTodo.FunctionId

  ResolverListTodos:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnListTodos.FunctionId

  ResolverTodosByOwner:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnTodosByOwner.FunctionId

  ############################################################################
  # Pipeline resolvers - Mutation
  ############################################################################
  ResolverCreateTodo:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnCreateTodo.FunctionId

  ResolverUpdateTodo:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnUpdateTodo.FunctionId

  ResolverDeleteTodo:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnDeleteTodo.FunctionId

  ############################################################################
  # Pipeline resolvers - Subscription
  ############################################################################
  ResolverOnCreateTodo:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Subscription
      FieldName: onCreateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnOnCreateTodo.FunctionId

  ResolverOnUpdateTodo:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Subscription
      FieldName: onUpdateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnOnUpdateTodo.FunctionId

  ResolverOnDeleteTodo:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Subscription
      FieldName: onDeleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt FnOnDeleteTodo.FunctionId

Outputs:
  GraphQLApiId:
    Description: AppSync GraphQL API ID
    Value: !GetAtt GraphQLApi.ApiId
  GraphQLApiArn:
    Description: AppSync GraphQL API ARN
    Value: !GetAtt GraphQLApi.Arn
  GraphQLApiUrl:
    Description: AppSync GraphQL API endpoint URL
    Value: !GetAtt GraphQLApi.GraphQLUrl
  GraphQLApiKey:
    Description: API key used to authenticate against the GraphQL API
    Value: !GetAtt ApiKey.ApiKey
  DynamoDBTableName:
    Description: Name of the DynamoDB table backing the API
    Value: !Ref TodoTable
  DynamoDBTableArn:
    Description: ARN of the DynamoDB table backing the API
    Value: !GetAtt TodoTable.Arn

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Serverless CRUD API for the "Kitten" service. Amazon API Gateway (REST) fronts five
  AWS Lambda functions that read and write a DynamoDB table named "Kitten" (on-demand
  billing, partition key "KittenId"). Exposes POST /kitten, GET /kitten,
  GET /kitten/{id}, PUT /kitten/{id}, DELETE /kitten/{id}, plus an OPTIONS (CORS)
  method on every resource.

Parameters:
  StageName:
    Type: String
    Default: prod
    MinLength: 1
    MaxLength: 128
    AllowedPattern: '^[a-zA-Z0-9_-]+$'
    ConstraintDescription: Must be a valid API Gateway stage name (letters, numbers, hyphens, underscores).
    Description: Name of the API Gateway stage to deploy the Kitten API to.

Resources:

  #############################################################################
  # DynamoDB table
  #############################################################################
  KittenTable:
    Type: AWS::DynamoDB::Table
    Properties:
      TableName: Kitten
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: KittenId
          AttributeType: S
      KeySchema:
        - AttributeName: KittenId
          KeyType: HASH
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      SSESpecification:
        SSEEnabled: true
      Tags:
        - Key: Service
          Value: Kitten
        - Key: ManagedBy
          Value: CloudFormation

  #############################################################################
  # IAM role shared by the Kitten Lambda functions
  #############################################################################
  KittenLambdaRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: !Sub '${AWS::StackName}-kitten-lambda-role'
      Description: Execution role for the Kitten CRUD Lambda functions
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Sid: AllowLambdaServiceToAssumeRole
            Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action:
              - sts:AssumeRole
      ManagedPolicyArns:
        - !Sub 'arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole'
      Policies:
        - PolicyName: KittenTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: KittenTableCrud
                Effect: Allow
                Action:
                  - dynamodb:PutItem
                  - dynamodb:GetItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Scan
                  - dynamodb:Query
                Resource:
                  - !GetAtt KittenTable.Arn

  #############################################################################
  # Lambda function - POST /kitten  (create)
  #############################################################################
  CreateKittenFunction:
    Type: AWS::Lambda::Function
    Properties:
      Description: Creates a Kitten item and returns it with an auto-generated KittenId
      FunctionName: !Sub '${AWS::StackName}-create-kitten'
      Runtime: nodejs20.x
      Handler: index.handler
      MemorySize: 256
      Timeout: 10
      Role: !GetAtt KittenLambdaRole.Arn
      Environment:
        Variables:
          TABLE_NAME: !Ref KittenTable
      Code:
        ZipFile: |
          'use strict';

          const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
          const { DynamoDBDocumentClient, PutCommand } = require('@aws-sdk/lib-dynamodb');

          const TABLE_NAME = process.env.TABLE_NAME;
          const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));

          const CORS_HEADERS = {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Headers': 'Content-Type,X-Amz-Date,Authorization,X-Api-Key,X-Amz-Security-Token',
            'Access-Control-Allow-Methods': 'OPTIONS,GET,POST,PUT,DELETE'
          };

          const reply = function (statusCode, payload) {
            return {
              statusCode: statusCode,
              headers: CORS_HEADERS,
              body: JSON.stringify(payload)
            };
          };

          exports.handler = async function (event, context) {
            let body;
            try {
              body = JSON.parse(event.body || '{}');
            } catch (err) {
              return reply(400, { message: 'Request body must be valid JSON' });
            }

            const name = body.name;
            const color = body.color;

            if (typeof name !== 'string' || name.trim() === '' ||
                typeof color !== 'string' || color.trim() === '') {
              return reply(400, { message: 'Both "name" and "color" are required' });
            }

            const item = {
              KittenId: context.awsRequestId,
              name: name.trim(),
              color: color.trim()
            };

            try {
              await docClient.send(new PutCommand({ TableName: TABLE_NAME, Item: item }));
              return reply(201, item);
            } catch (err) {
              console.error('CreateKitten failed', err);
              return reply(500, { message: 'Internal server error' });
            }
          };

  #############################################################################
  # Lambda function - GET /kitten  (list / scan)
  #############################################################################
  ListKittensFunction:
    Type: AWS::Lambda::Function
    Properties:
      Description: Scans and returns every Kitten item
      FunctionName: !Sub '${AWS::StackName}-list-kittens'
      Runtime: nodejs20.x
      Handler: index.handler
      MemorySize: 256
      Timeout: 10
      Role: !GetAtt KittenLambdaRole.Arn
      Environment:
        Variables:
          TABLE_NAME: !Ref KittenTable
      Code:
        ZipFile: |
          'use strict';

          const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
          const { DynamoDBDocumentClient, ScanCommand } = require('@aws-sdk/lib-dynamodb');

          const TABLE_NAME = process.env.TABLE_NAME;
          const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));

          const CORS_HEADERS = {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Headers': 'Content-Type,X-Amz-Date,Authorization,X-Api-Key,X-Amz-Security-Token',
            'Access-Control-Allow-Methods': 'OPTIONS,GET,POST,PUT,DELETE'
          };

          const reply = function (statusCode, payload) {
            return {
              statusCode: statusCode,
              headers: CORS_HEADERS,
              body: JSON.stringify(payload)
            };
          };

          exports.handler = async function () {
            try {
              const result = await docClient.send(new ScanCommand({ TableName: TABLE_NAME }));
              const items = result.Items || [];
              return reply(200, { count: items.length, items: items });
            } catch (err) {
              console.error('ListKittens failed', err);
              return reply(500, { message: 'Internal server error' });
            }
          };

  #############################################################################
  # Lambda function - GET /kitten/{id}  (read one)
  #############################################################################
  GetKittenFunction:
    Type: AWS::Lambda::Function
    Properties:
      Description: Returns a single Kitten item by KittenId
      FunctionName: !Sub '${AWS::StackName}-get-kitten'
      Runtime: nodejs20.x
      Handler: index.handler
      MemorySize: 256
      Timeout: 10
      Role: !GetAtt KittenLambdaRole.Arn
      Environment:
        Variables:
          TABLE_NAME: !Ref KittenTable
      Code:
        ZipFile: |
          'use strict';

          const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
          const { DynamoDBDocumentClient, GetCommand } = require('@aws-sdk/lib-dynamodb');

          const TABLE_NAME = process.env.TABLE_NAME;
          const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));

          const CORS_HEADERS = {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Headers': 'Content-Type,X-Amz-Date,Authorization,X-Api-Key,X-Amz-Security-Token',
            'Access-Control-Allow-Methods': 'OPTIONS,GET,POST,PUT,DELETE'
          };

          const reply = function (statusCode, payload) {
            return {
              statusCode: statusCode,
              headers: CORS_HEADERS,
              body: JSON.stringify(payload)
            };
          };

          exports.handler = async function (event) {
            const kittenId = event.pathParameters && event.pathParameters.id;

            if (!kittenId || kittenId.trim() === '') {
              return reply(400, { message: 'Kitten id path parameter is required' });
            }

            try {
              const result = await docClient.send(new GetCommand({
                TableName: TABLE_NAME,
                Key: { KittenId: kittenId }
              }));

              if (!result.Item) {
                return reply(404, { message: 'Kitten not found' });
              }

              return reply(200, result.Item);
            } catch (err) {
              console.error('GetKitten failed', err);
              return reply(500, { message: 'Internal server error' });
            }
          };

  #############################################################################
  # Lambda function - PUT /kitten/{id}  (replace)
  #############################################################################
  UpdateKittenFunction:
    Type: AWS::Lambda::Function
    Properties:
      Description: Replaces an existing Kitten item identified by KittenId
      FunctionName: !Sub '${AWS::StackName}-update-kitten'
      Runtime: nodejs20.x
      Handler: index.handler
      MemorySize: 256
      Timeout: 10
      Role: !GetAtt KittenLambdaRole.Arn
      Environment:
        Variables:
          TABLE_NAME: !Ref KittenTable
      Code:
        ZipFile: |
          'use strict';

          const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
          const { DynamoDBDocumentClient, PutCommand } = require('@aws-sdk/lib-dynamodb');

          const TABLE_NAME = process.env.TABLE_NAME;
          const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));

          const CORS_HEADERS = {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Headers': 'Content-Type,X-Amz-Date,Authorization,X-Api-Key,X-Amz-Security-Token',
            'Access-Control-Allow-Methods': 'OPTIONS,GET,POST,PUT,DELETE'
          };

          const reply = function (statusCode, payload) {
            return {
              statusCode: statusCode,
              headers: CORS_HEADERS,
              body: JSON.stringify(payload)
            };
          };

          exports.handler = async function (event) {
            const kittenId = event.pathParameters && event.pathParameters.id;

            if (!kittenId || kittenId.trim() === '') {
              return reply(400, { message: 'Kitten id path parameter is required' });
            }

            let body;
            try {
              body = JSON.parse(event.body || '{}');
            } catch (err) {
              return reply(400, { message: 'Request body must be valid JSON' });
            }

            const name = body.name;
            const color = body.color;

            if (typeof name !== 'string' || name.trim() === '' ||
                typeof color !== 'string' || color.trim() === '') {
              return reply(400, { message: 'Both "name" and "color" are required' });
            }

            const item = {
              KittenId: kittenId,
              name: name.trim(),
              color: color.trim()
            };

            try {
              await docClient.send(new PutCommand({
                TableName: TABLE_NAME,
                Item: item,
                ConditionExpression: 'attribute_exists(KittenId)'
              }));
              return reply(200, item);
            } catch (err) {
              if (err && err.name === 'ConditionalCheckFailedException') {
                return reply(404, { message: 'Kitten not found' });
              }
              console.error('UpdateKitten failed', err);
              return reply(500, { message: 'Internal server error' });
            }
          };

  #############################################################################
  # Lambda function - DELETE /kitten/{id}  (delete)
  #############################################################################
  DeleteKittenFunction:
    Type: AWS::Lambda::Function
    Properties:
      Description: Deletes a Kitten item identified by KittenId
      FunctionName: !Sub '${AWS::StackName}-delete-kitten'
      Runtime: nodejs20.x
      Handler: index.handler
      MemorySize: 256
      Timeout: 10
      Role: !GetAtt KittenLambdaRole.Arn
      Environment:
        Variables:
          TABLE_NAME: !Ref KittenTable
      Code:
        ZipFile: |
          'use strict';

          const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
          const { DynamoDBDocumentClient, DeleteCommand } = require('@aws-sdk/lib-dynamodb');

          const TABLE_NAME = process.env.TABLE_NAME;
          const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));

          const CORS_HEADERS = {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Headers': 'Content-Type,X-Amz-Date,Authorization,X-Api-Key,X-Amz-Security-Token',
            'Access-Control-Allow-Methods': 'OPTIONS,GET,POST,PUT,DELETE'
          };

          const reply = function (statusCode, payload) {
            return {
              statusCode: statusCode,
              headers: CORS_HEADERS,
              body: JSON.stringify(payload)
            };
          };

          exports.handler = async function (event) {
            const kittenId = event.pathParameters && event.pathParameters.id;

            if (!kittenId || kittenId.trim() === '') {
              return reply(400, { message: 'Kitten id path parameter is required' });
            }

            try {
              const result = await docClient.send(new DeleteCommand({
                TableName: TABLE_NAME,
                Key: { KittenId: kittenId },
                ReturnValues: 'ALL_OLD'
              }));

              if (!result.Attributes) {
                return reply(404, { message: 'Kitten not found' });
              }

              return reply(200, { message: 'Kitten deleted', KittenId: kittenId });
            } catch (err) {
              console.error('DeleteKitten failed', err);
              return reply(500, { message: 'Internal server error' });
            }
          };

  #############################################################################
  # API Gateway REST API and resources
  #############################################################################
  KittenApi:
    Type: AWS::ApiGateway::RestApi
    Properties:
      Name: !Sub '${AWS::StackName}-kitten-api'
      Description: Serverless CRUD API for the Kitten service
      EndpointConfiguration:
        Types:
          - REGIONAL

  KittenResource:
    Type: AWS::ApiGateway::Resource
    Properties:
      RestApiId: !Ref KittenApi
      ParentId: !GetAtt KittenApi.RootResourceId
      PathPart: kitten

  KittenIdResource:
    Type: AWS::ApiGateway::Resource
    Properties:
      RestApiId: !Ref KittenApi
      ParentId: !Ref KittenResource
      PathPart: '{id}'

  #############################################################################
  # /kitten methods
  #############################################################################
  KittenPostMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref KittenApi
      ResourceId: !Ref KittenResource
      HttpMethod: POST
      AuthorizationType: NONE
      ApiKeyRequired: false
      Integration:
        Type: AWS_PROXY
        IntegrationHttpMethod: POST
        Uri: !Sub 'arn:${AWS::Partition}:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${CreateKittenFunction.Arn}/invocations'

  KittenGetMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref KittenApi
      ResourceId: !Ref KittenResource
      HttpMethod: GET
      AuthorizationType: NONE
      ApiKeyRequired: false
      Integration:
        Type: AWS_PROXY
        IntegrationHttpMethod: POST
        Uri: !Sub 'arn:${AWS::Partition}:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${ListKittensFunction.Arn}/invocations'

  KittenOptionsMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref KittenApi
      ResourceId: !Ref KittenResource
      HttpMethod: OPTIONS
      AuthorizationType: NONE
      ApiKeyRequired: false
      Integration:
        Type: MOCK
        PassthroughBehavior: WHEN_NO_MATCH
        RequestTemplates:
          application/json: '{"statusCode": 200}'
        IntegrationResponses:
          - StatusCode: '200'
            ResponseParameters:
              method.response.header.Access-Control-Allow-Origin: "'*'"
              method.response.header.Access-Control-Allow-Headers: "'Content-Type,X-Amz-Date,Authorization,X-Api-Key,X-Amz-Security-Token'"
              method.response.header.Access-Control-Allow-Methods: "'OPTIONS,GET,POST,PUT,DELETE'"
            ResponseTemplates:
              application/json: ''
      MethodResponses:
        - StatusCode: '200'
          ResponseParameters:
            method.response.header.Access-Control-Allow-Origin: true
            method.response.header.Access-Control-Allow-Headers: true
            method.response.header.Access-Control-Allow-Methods: true

  #############################################################################
  # /kitten/{id} methods
  #############################################################################
  KittenIdGetMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref KittenApi
      ResourceId: !Ref KittenIdResource
      HttpMethod: GET
      AuthorizationType: NONE
      ApiKeyRequired: false
      RequestParameters:
        method.request.path.id: true
      Integration:
        Type: AWS_PROXY
        IntegrationHttpMethod: POST
        Uri: !Sub 'arn:${AWS::Partition}:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${GetKittenFunction.Arn}/invocations'

  KittenIdPutMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref KittenApi
      ResourceId: !Ref KittenIdResource
      HttpMethod: PUT
      AuthorizationType: NONE
      ApiKeyRequired: false
      RequestParameters:
        method.request.path.id: true
      Integration:
        Type: AWS_PROXY
        IntegrationHttpMethod: POST
        Uri: !Sub 'arn:${AWS::Partition}:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${UpdateKittenFunction.Arn}/invocations'

  KittenIdDeleteMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref KittenApi
      ResourceId: !Ref KittenIdResource
      HttpMethod: DELETE
      AuthorizationType: NONE
      ApiKeyRequired: false
      RequestParameters:
        method.request.path.id: true
      Integration:
        Type: AWS_PROXY
        IntegrationHttpMethod: POST
        Uri: !Sub 'arn:${AWS::Partition}:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${DeleteKittenFunction.Arn}/invocations'

  KittenIdOptionsMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref KittenApi
      ResourceId: !Ref KittenIdResource
      HttpMethod: OPTIONS
      AuthorizationType: NONE
      ApiKeyRequired: false
      Integration:
        Type: MOCK
        PassthroughBehavior: WHEN_NO_MATCH
        RequestTemplates:
          application/json: '{"statusCode": 200}'
        IntegrationResponses:
          - StatusCode: '200'
            ResponseParameters:
              method.response.header.Access-Control-Allow-Origin: "'*'"
              method.response.header.Access-Control-Allow-Headers: "'Content-Type,X-Amz-Date,Authorization,X-Api-Key,X-Amz-Security-Token'"
              method.response.header.Access-Control-Allow-Methods: "'OPTIONS,GET,POST,PUT,DELETE'"
            ResponseTemplates:
              application/json: ''
      MethodResponses:
        - StatusCode: '200'
          ResponseParameters:
            method.response.header.Access-Control-Allow-Origin: true
            method.response.header.Access-Control-Allow-Headers: true
            method.response.header.Access-Control-Allow-Methods: true

  #############################################################################
  # CORS pre-flight on the API root resource
  #############################################################################
  KittenRootOptionsMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref KittenApi
      ResourceId: !GetAtt KittenApi.RootResourceId
      HttpMethod: OPTIONS
      AuthorizationType: NONE
      ApiKeyRequired: false
      Integration:
        Type: MOCK
        PassthroughBehavior: WHEN_NO_MATCH
        RequestTemplates:
          application/json: '{"statusCode": 200}'
        IntegrationResponses:
          - StatusCode: '200'
            ResponseParameters:
              method.response.header.Access-Control-Allow-Origin: "'*'"
              method.response.header.Access-Control-Allow-Headers: "'Content-Type,X-Amz-Date,Authorization,X-Api-Key,X-Amz-Security-Token'"
              method.response.header.Access-Control-Allow-Methods: "'OPTIONS,GET,POST,PUT,DELETE'"
            ResponseTemplates:
              application/json: ''
      MethodResponses:
        - StatusCode: '200'
          ResponseParameters:
            method.response.header.Access-Control-Allow-Origin: true
            method.response.header.Access-Control-Allow-Headers: true
            method.response.header.Access-Control-Allow-Methods: true

  #############################################################################
  # Lambda invoke permissions for API Gateway
  #############################################################################
  CreateKittenInvokePermission:
    Type: AWS::Lambda::Permission
    Properties:
      Action: lambda:InvokeFunction
      FunctionName: !Ref CreateKittenFunction
      Principal: apigateway.amazonaws.com
      SourceArn: !Sub 'arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${KittenApi}/*/POST/kitten'

  ListKittensInvokePermission:
    Type: AWS::Lambda::Permission
    Properties:
      Action: lambda:InvokeFunction
      FunctionName: !Ref ListKittensFunction
      Principal: apigateway.amazonaws.com
      SourceArn: !Sub 'arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${KittenApi}/*/GET/kitten'

  GetKittenInvokePermission:
    Type: AWS::Lambda::Permission
    Properties:
      Action: lambda:InvokeFunction
      FunctionName: !Ref GetKittenFunction
      Principal: apigateway.amazonaws.com
      SourceArn: !Sub 'arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${KittenApi}/*/GET/kitten/*'

  UpdateKittenInvokePermission:
    Type: AWS::Lambda::Permission
    Properties:
      Action: lambda:InvokeFunction
      FunctionName: !Ref UpdateKittenFunction
      Principal: apigateway.amazonaws.com
      SourceArn: !Sub 'arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${KittenApi}/*/PUT/kitten/*'

  DeleteKittenInvokePermission:
    Type: AWS::Lambda::Permission
    Properties:
      Action: lambda:InvokeFunction
      FunctionName: !Ref DeleteKittenFunction
      Principal: apigateway.amazonaws.com
      SourceArn: !Sub 'arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${KittenApi}/*/DELETE/kitten/*'

  #############################################################################
  # API Gateway deployment and stage
  #############################################################################
  KittenApiDeployment:
    Type: AWS::ApiGateway::Deployment
    DependsOn:
      - KittenPostMethod
      - KittenGetMethod
      - KittenOptionsMethod
      - KittenIdGetMethod
      - KittenIdPutMethod
      - KittenIdDeleteMethod
      - KittenIdOptionsMethod
      - KittenRootOptionsMethod
      - CreateKittenInvokePermission
      - ListKittensInvokePermission
      - GetKittenInvokePermission
      - UpdateKittenInvokePermission
      - DeleteKittenInvokePermission
    Properties:
      RestApiId: !Ref KittenApi
      Description: Deployment of the Kitten CRUD API

  KittenApiStage:
    Type: AWS::ApiGateway::Stage
    Properties:
      RestApiId: !Ref KittenApi
      DeploymentId: !Ref KittenApiDeployment
      StageName: !Ref StageName
      Description: Stage for the Kitten CRUD API
      MethodSettings:
        - ResourcePath: '/*'
          HttpMethod: '*'
          MetricsEnabled: true
          ThrottlingRateLimit: 100
          ThrottlingBurstLimit: 200

Outputs:
  ApiEndpoint:
    Description: Base invoke URL of the Kitten CRUD API
    Value: !Sub 'https://${KittenApi}.execute-api.${AWS::Region}.amazonaws.com/${StageName}'

  KittenCollectionUrl:
    Description: URL of the /kitten collection resource (POST to create, GET to list)
    Value: !Sub 'https://${KittenApi}.execute-api.${AWS::Region}.amazonaws.com/${StageName}/kitten'

  KittenItemUrl:
    Description: URL of the /kitten/{id} item resource (replace {id} with a KittenId)
    Value: !Sub 'https://${KittenApi}.execute-api.${AWS::Region}.amazonaws.com/${StageName}/kitten/{id}'

  KittenTableName:
    Description: Name of the DynamoDB table that stores the kittens
    Value: !Ref KittenTable

  KittenTableArn:
    Description: ARN of the DynamoDB table that stores the kittens
    Value: !GetAtt KittenTable.Arn

  RestApiId:
    Description: ID of the API Gateway REST API
    Value: !Ref KittenApi

  LambdaExecutionRoleArn:
    Description: ARN of the IAM role used by the Kitten Lambda functions
    Value: !GetAtt KittenLambdaRole.Arn

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Serverless Stripe to Squarespace to Slack webhook pipeline. Creates an API Gateway REST API
  (POST /webhooks, prod stage) backed by a Lambda function that validates the Stripe webhook
  signature, enriches the sale with Squarespace order and inventory data, and publishes a
  formatted notification to an SNS topic used for Slack relay. Also creates the Lambda
  execution role, the API Gateway invoke permission, the function log group, and a CloudWatch
  alarm that fires when invocation errors exceed zero within a one-minute period.

Parameters:
  StripeWebhookSecret:
    Type: String
    NoEcho: true
    MinLength: 1
    Description: >-
      Stripe webhook signing secret (whsec_...) used to verify the Stripe-Signature header of
      every incoming webhook request. Stored as a Lambda environment variable.
  SquarespaceApiToken:
    Type: String
    NoEcho: true
    MinLength: 1
    Description: >-
      Squarespace Commerce API key used to look up order and inventory details. Sent as the
      Bearer token on calls to the api.squarespace.com Commerce API.

Resources:
  SalesNotificationTopic:
    Type: AWS::SNS::Topic
    Properties:
      TopicName: !Sub '${AWS::StackName}-sales-notifications'
      DisplayName: Stripe and Squarespace sale notifications for Slack

  WebhookLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/lambda/${AWS::StackName}-stripe-squarespace-webhook'
      RetentionInDays: 30

  WebhookFunctionRole:
    Type: AWS::IAM::Role
    Properties:
      Description: >-
        Execution role for the Stripe and Squarespace webhook handler. Grants CloudWatch Logs
        access and permission to publish sale notifications to the stack SNS topic.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - !Sub 'arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole'
      Policies:
        - PolicyName: PublishSaleNotifications
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: PublishToSalesNotificationTopic
                Effect: Allow
                Action:
                  - sns:Publish
                Resource: !Ref SalesNotificationTopic

  WebhookFunction:
    Type: AWS::Lambda::Function
    DependsOn:
      - WebhookLogGroup
    Properties:
      FunctionName: !Sub '${AWS::StackName}-stripe-squarespace-webhook'
      Description: >-
        Validates Stripe webhook events, enriches the sale with Squarespace order and inventory
        data and publishes a formatted notification to SNS for relay to Slack.
      Runtime: nodejs20.x
      Handler: index.handler
      Role: !GetAtt WebhookFunctionRole.Arn
      MemorySize: 256
      Timeout: 25
      Environment:
        Variables:
          SNS_TOPIC_ARN: !Ref SalesNotificationTopic
          STRIPE_WEBHOOK_SECRET: !Ref StripeWebhookSecret
          SQUARESPACE_API_TOKEN: !Ref SquarespaceApiToken
          NODE_OPTIONS: '--enable-source-maps'
      Code:
        ZipFile: |
          const crypto = require('crypto');
          const https = require('https');
          const { SNSClient, PublishCommand } = require('@aws-sdk/client-sns');

          const sns = new SNSClient({});
          const SECRET = process.env.STRIPE_WEBHOOK_SECRET;
          const TOKEN = process.env.SQUARESPACE_API_TOKEN;
          const TOPIC = process.env.SNS_TOPIC_ARN;
          const TYPES = ['checkout.session.completed', 'order.created', 'payment_intent.succeeded'];

          const verified = (body, sig) => {
            const parts = String(sig || '').split(',');
            const t = (parts.find((p) => p.startsWith('t=')) || '').slice(2);
            const sigs = parts.filter((p) => p.startsWith('v1=')).map((p) => p.slice(3));
            if (!t || !sigs.length || Math.abs(Date.now() / 1000 - Number(t)) > 300) return false;
            const want = crypto.createHmac('sha256', SECRET).update(t + '.' + body).digest('hex');
            return sigs.some((s) => s.length === want.length && crypto.timingSafeEqual(Buffer.from(s), Buffer.from(want)));
          };

          const sqsp = (path) => new Promise((resolve, reject) => {
            const req = https.request({
              host: 'api.squarespace.com',
              path: path,
              method: 'GET',
              timeout: 5000,
              headers: {
                Authorization: 'Bearer ' + TOKEN,
                'User-Agent': 'lambda-stripe-squarespace-webhook/1.0',
                Accept: 'application/json'
              }
            }, (res) => {
              let data = '';
              res.on('data', (c) => { data += c; });
              res.on('end', () => {
                if (res.statusCode < 200 || res.statusCode > 299) return reject(new Error('HTTP ' + res.statusCode + ': ' + data.slice(0, 200)));
                try { return resolve(JSON.parse(data || '{}')); } catch (e) { return reject(e); }
              });
            });
            req.on('error', reject);
            req.on('timeout', () => req.destroy(new Error('timeout')));
            req.end();
          });

          exports.handler = async (event) => {
            const body = event.isBase64Encoded ? Buffer.from(event.body || '', 'base64').toString('utf8') : (event.body || '');
            const sig = event.headers ? (event.headers['stripe-signature'] || event.headers['Stripe-Signature'] || '') : '';
            if (!verified(body, sig)) {
              console.error('Invalid Stripe signature');
              return { statusCode: 400, body: 'invalid signature' };
            }

            const evt = JSON.parse(body);
            if (!TYPES.includes(evt.type)) {
              console.log('Ignored Stripe event ' + evt.type);
              return { statusCode: 200, body: 'ignored' };
            }

            const data = (evt.data && evt.data.object) || {};
            const meta = data.metadata || {};
            const orderId = meta.squarespaceOrderId || meta.orderId || data.client_reference_id;
            if (!orderId) {
              console.error('No Squarespace order reference on event ' + evt.id);
              return { statusCode: 422, body: 'missing squarespace order id' };
            }

            const order = await sqsp('/1.0/commerce/orders/' + encodeURIComponent(orderId));
            const items = order.lineItems || [];
            const stock = [];
            for (const item of items.slice(0, 5)) {
              if (!item.productId) continue;
              try {
                const p = await sqsp('/1.0/commerce/products/' + encodeURIComponent(item.productId));
                const vs = p.variants || [];
                const v = vs.find((x) => x.sku && x.sku === item.sku) || vs[0];
                if (v && v.stock) {
                  stock.push('  - ' + (v.sku || 'unknown-sku') + ': ' + (v.stock.unlimited ? 'unlimited' : v.stock.quantity) + ' in stock');
                }
              } catch (err) {
                console.warn('Inventory lookup failed: ' + err.message);
              }
            }

            const num = String(order.orderNumber || order.id || orderId);
            const total = order.grandTotal ? order.grandTotal.value + ' ' + (order.grandTotal.currency || '') : 'n/a';
            const itemLines = items.length
              ? items.map((i) => '  - ' + (i.sku || i.productId || 'no-sku') + ' x' + (i.quantity || 0) + ' ' + (i.productName || 'item'))
              : ['  - no line items reported'];

            const message = [
              ':moneybag: New Squarespace sale received from Stripe',
              'Order: ' + num,
              'Customer: ' + (order.customerEmail || 'unknown'),
              'Total: ' + total,
              'Fulfillment: ' + (order.fulfillmentStatus || 'unknown'),
              'Items:'
            ].concat(itemLines, ['Inventory:'], stock.length ? stock : ['  - inventory details unavailable'], [
              'Stripe event: ' + (evt.id || 'n/a') + ' (' + evt.type + ')'
            ]).join('\n');

            await sns.send(new PublishCommand({
              TopicArn: TOPIC,
              Subject: ('New Squarespace sale ' + num).slice(0, 100),
              Message: message
            }));

            console.log('Published sale notification for order ' + num);
            return { statusCode: 200, body: JSON.stringify({ orderNumber: num }) };
          };

  WebhookApi:
    Type: AWS::ApiGateway::RestApi
    Properties:
      Name: !Sub '${AWS::StackName}-stripe-squarespace-webhook-api'
      Description: REST API that receives Stripe webhook events and forwards them to the webhook Lambda function.
      EndpointConfiguration:
        Types:
          - REGIONAL

  WebhookResource:
    Type: AWS::ApiGateway::Resource
    Properties:
      RestApiId: !Ref WebhookApi
      ParentId: !GetAtt WebhookApi.RootResourceId
      PathPart: webhooks

  WebhookPostMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref WebhookApi
      ResourceId: !Ref WebhookResource
      HttpMethod: POST
      AuthorizationType: NONE
      ApiKeyRequired: false
      Integration:
        Type: AWS_PROXY
        IntegrationHttpMethod: POST
        Uri: !Sub 'arn:${AWS::Partition}:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${WebhookFunction.Arn}/invocations'

  WebhookDeployment:
    Type: AWS::ApiGateway::Deployment
    DependsOn:
      - WebhookPostMethod
    Properties:
      RestApiId: !Ref WebhookApi
      StageName: prod
      Description: Production stage hosting the Stripe webhook endpoint.

  WebhookInvokePermission:
    Type: AWS::Lambda::Permission
    Properties:
      Action: lambda:InvokeFunction
      FunctionName: !Ref WebhookFunction
      Principal: apigateway.amazonaws.com
      SourceArn: !Sub 'arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${WebhookApi}/*/POST/webhooks'

  WebhookErrorAlarm:
    Type: AWS::CloudWatch::Alarm
    Properties:
      AlarmName: !Sub '${AWS::StackName}-stripe-squarespace-webhook-errors'
      AlarmDescription: >-
        Fires when the Stripe and Squarespace webhook handler reports one or more invocation
        errors within a one-minute period.
      Namespace: AWS/Lambda
      MetricName: Errors
      Dimensions:
        - Name: FunctionName
          Value: !Ref WebhookFunction
      Statistic: Sum
      Period: 60
      EvaluationPeriods: 1
      DatapointsToAlarm: 1
      Threshold: 0
      ComparisonOperator: GreaterThanThreshold
      TreatMissingData: notBreaching
      AlarmActions:
        - !Ref SalesNotificationTopic

Outputs:
  WebhookEndpointUrl:
    Description: Public endpoint URL to register in the Stripe dashboard as the webhook receiver.
    Value: !Sub 'https://${WebhookApi}.execute-api.${AWS::Region}.amazonaws.com/prod/webhooks'
  SalesNotificationTopicArn:
    Description: ARN of the SNS topic that carries sale notifications; subscribe the Slack relay here.
    Value: !Ref SalesNotificationTopic
  WebhookFunctionName:
    Description: Name of the webhook handler Lambda function.
    Value: !Ref WebhookFunction
  WebhookFunctionArn:
    Description: ARN of the webhook handler Lambda function.
    Value: !GetAtt WebhookFunction.Arn
  WebhookLogGroupName:
    Description: CloudWatch Logs log group receiving the webhook handler's logs.
    Value: !Ref WebhookLogGroup

AWSTemplateFormatVersion: '2010-09-09'
Description: Simple Todo API - AWS AppSync GraphQL API with JavaScript resolvers backed by an Amazon DynamoDB table, protected by API key authentication.

Resources:

  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      TableName: !Sub '${AWS::StackName}-todo-table'
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      SSESpecification:
        SSEEnabled: true

  AppSyncTodoTableRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: !Sub '${AWS::StackName}-appsync-todo-role'
      Description: Service role assumed by AppSync to read and write the Todo DynamoDB table
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                  - dynamodb:ConditionCheckItem
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  SimpleTodoAPI:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
      XrayEnabled: true

  SimpleTodoAPISchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          description: String
          owner: String
          completed: Boolean
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        input CreateTodoInput {
          id: ID
          title: String!
          description: String
          owner: String
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          completed: Boolean
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          todosByOwner(owner: String!): [Todo]
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

  TodoTableDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncTodoTableRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region
        UseCallerCredentials: false

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = input.id || util.autoId();
          const now = util.time.nowISO8601();

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues({
              ...input,
              id,
              createdAt: now,
              updatedAt: now,
            }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = input.id;

          const sets = [];
          const expressionNames = {};
          const values = {};

          Object.keys(input).forEach((key) => {
            if (key === 'id') return;
            const value = input[key];
            if (value === undefined || value === null) return;
            const nameKey = '#' + key;
            const valueKey = ':' + key;
            expressionNames[nameKey] = key;
            values[valueKey] = value;
            sets.push(nameKey + ' = ' + valueKey);
          });

          expressionNames['#updatedAt'] = 'updatedAt';
          values[':updatedAt'] = util.time.nowISO8601();
          sets.push('#updatedAt = :updatedAt');

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames,
              expressionValues: util.dynamodb.toMapValues(values),
            },
            condition: {
              expression: 'attribute_exists(#pk)',
              expressionNames: { '#pk': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Scan',
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner }),
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

  SimpleTodoAPIKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Description: API key for testing the SimpleTodoAPI GraphQL endpoint

Outputs:

  SimpleTodoAPIId:
    Description: The ID of the SimpleTodoAPI AppSync GraphQL API
    Value: !GetAtt SimpleTodoAPI.ApiId

  SimpleTodoAPIUrl:
    Description: The GraphQL endpoint URL of the SimpleTodoAPI
    Value: !GetAtt SimpleTodoAPI.GraphQLUrl

  SimpleTodoAPIKeyId:
    Description: The ID of the API key used to authenticate calls to the SimpleTodoAPI
    Value: !GetAtt SimpleTodoAPIKey.ApiKeyId

  SimpleTodoAPIKeyValue:
    Description: The API key value to use in the x-api-key header when testing the SimpleTodoAPI
    Value: !GetAtt SimpleTodoAPIKey.ApiKey

  TodoTableName:
    Description: The name of the DynamoDB table backing the SimpleTodoAPI
    Value: !Ref TodoTable
